  DEFAULT_CAPTION_PAGE_SIZE,
  MAX_CAPTION_PAGE_SIZE,
  decodeCaptionCursor,
  encodeCaptionCursor,
  getCaptionHistoryPage,
  normalizeCaptionSegment
};

